<h5 class="mb-3">Datos personales</h5><form id="form-datos-inscripcion" class="row g-3"><div class="col-md-3"><label class="form-label">Tipo documento *</label><input class="form-control" name="pos_tdo_ide" type="number" value="<?= esc($postulante['pos_tdo_ide']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Documento *</label><input class="form-control" name="pos_documento" value="<?= esc($postulante['pos_documento']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Nombres *</label><input class="form-control" name="pos_nombres" value="<?= esc($postulante['pos_nombres']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Apellido paterno *</label><input class="form-control" name="pos_apellido_paterno" value="<?= esc($postulante['pos_apellido_paterno']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Apellido materno</label><input class="form-control" name="pos_apellido_materno" value="<?= esc($postulante['pos_apellido_materno']??'') ?>"></div><div class="col-md-3"><label class="form-label">Nacimiento</label><input class="form-control" name="pos_fecha_nacimiento" type="date" value="<?= esc($postulante['pos_fecha_nacimiento']??'') ?>"></div><div class="col-md-3"><label class="form-label">Sexo</label><select class="form-select" name="pos_sexo"><option value="">Seleccione</option><option <?= ($postulante['pos_sexo']??'')==='MASCULINO'?'selected':'' ?>>MASCULINO</option><option <?= ($postulante['pos_sexo']??'')==='FEMENINO'?'selected':'' ?>>FEMENINO</option></select></div><div class="col-md-3"><label class="form-label">Teléfono</label><input class="form-control" name="pos_telefono" value="<?= esc($postulante['pos_telefono']??'') ?>"></div><div class="col-md-6"><label class="form-label">Correo *</label><input class="form-control" name="pos_email" type="email" value="<?= esc($postulante['pos_email']??'') ?>" required></div><div class="col-md-6"><label class="form-label">Dirección</label><input class="form-control" name="pos_direccion" value="<?= esc($postulante['pos_direccion']??'') ?>"></div><?php if($editable): ?><div class="col-12"><button class="btn btn-primary">Guardar datos personales</button></div><?php endif ?></form><script>$('#form-datos-inscripcion').on('submit',function(e){e.preventDefault();$.post('<?= base_url('seleccion/postulacion/inscripcion/datos/'.$convocatoriaId) ?>',$(this).serialize()).done(r=>r.status?toastr.success(r.message):toastr.error(r.message)).fail(x=>toastr.error(x.responseJSON?.message||'No se pudo guardar'));});</script>
